// Fecha a medicao do ciclo completo e monta as duas linhas que vao ao Postgres.
// Nada identificavel entra aqui: o objeto e montado campo a campo, e do texto
// do caso so sobrevive a contagem de caracteres.
const d = $('Parse Classificação').first().json;
const e = $('Sanitizar Entrada').first().json;
const t_fim = Date.now();
const t0 = new Date(e.recebido_em).getTime();

// Com onError continueRegularOutput nos nos do Slack, a falha de entrega chega
// aqui como item de erro em vez de interromper o fluxo. Registrar isso e o
// ponto: o caso foi classificado, o formulario respondeu sucesso ao cliente, e
// ninguem recebeu o caso. E o pior modo de falha do sistema, e o unico que a
// metrica de erro nao enxergaria se o registro se perdesse junto.
const falhouEntrega = !!($json && $json.error);
const erroEntrega = falhouEntrega
  ? String($json.error.message || $json.error).slice(0, 180)
  : null;

const trilha = {
  protocolo: d.protocolo,
  recebido_em: d.recebido_em,
  latencia_ms: d.latencia_ms,
  duracao_total_ms: t_fim - t0,
  duracao_resposta_ms: d.t_parse_fim - t0,
  area: d.revisao_manual ? null : d.area,
  urgencia: d.urgencia,
  revisao_manual: d.revisao_manual,
  motivo_revisao: d.motivo_revisao || erroEntrega,
  origem: d.origem,
  caracteres_descricao: String(e.descricao_caso || '').length,
  modelo: d.modelo,
  tokens_entrada: d.tokens_entrada,
  tokens_saida: d.tokens_saida,
  status: falhouEntrega ? 'erro' : (d.revisao_manual ? 'revisao_manual' : 'sucesso'),
  causa_falha: falhouEntrega ? 'slack' : null,
};

// Quatro spans medidos, e nao sete. Os carimbos disponiveis delimitam quatro
// trechos; declarar sete daria aparencia de granularidade que nao existe.
// 'entrega_slack' engloba o roteamento, que e barato e nao tem carimbo proprio.
const spans = [
  ['sanitizacao',       t0,                  e.t_sanitizacao_fim],
  ['classificacao_llm', e.t_sanitizacao_fim, d.t_parse_inicio],
  ['parse',             d.t_parse_inicio,    d.t_parse_fim],
  ['entrega_slack',     d.t_parse_fim,       t_fim],
].map(function (x) {
  return {
    protocolo: d.protocolo,
    span: x[0],
    inicio: new Date(x[1]).toISOString(),
    fim: new Date(x[2]).toISOString(),
    duracao_ms: Math.max(0, x[2] - x[1]),
    status: (x[0] === 'entrega_slack' && falhouEntrega) ? 'erro'
          : (x[0] === 'classificacao_llm' && d.revisao_manual) ? 'erro'
          : 'ok',
  };
});

return [{ json: { trilha: trilha, spans: spans } }];
